import Foundation
import CryptoKit
@testable import QAudionEngine

/// The shared vectors of NFC pairing v2 (nfc-pairing-kat.json, generated by scripts/kat/gen_nfc_pairing_kat.py).
/// A byte-for-byte copy of that file is a test resource; `NfcPairingV2KatTests` pins its SHA-256.
struct NfcPairingV2Kat {

    struct KatError: Error, CustomStringConvertible {
        let description: String
    }

    /// SHA-256 of the file, as pinned by the specification and by the Android app.
    static let sha256Hex = "5a1049235528c129f62c000ec0bc29b3f6b8258f51a1ccaa1250161451c7100b"

    let rawFile: Data
    let root: [String: Any]

    static func load() throws -> NfcPairingV2Kat {
        guard let url = Bundle.module.url(forResource: "nfc-pairing-kat", withExtension: "json") else {
            throw KatError(description: "nfc-pairing-kat.json not found in the test bundle")
        }
        let raw = try Data(contentsOf: url)
        guard let object = try JSONSerialization.jsonObject(with: raw) as? [String: Any] else {
            throw KatError(description: "malformed KAT JSON")
        }
        return NfcPairingV2Kat(rawFile: raw, root: object)
    }

    static func data(_ hex: String) throws -> Data {
        let chars = Array(hex.utf8)
        guard chars.count % 2 == 0 else { throw KatError(description: "odd hex length") }
        var out = Data(capacity: chars.count / 2)
        var i = 0
        func nibble(_ c: UInt8) throws -> UInt8 {
            switch c {
            case 0x30...0x39: return c - 0x30
            case 0x61...0x66: return c - 0x61 + 10
            default: throw KatError(description: "bad hex digit")
            }
        }
        while i < chars.count {
            out.append((try nibble(chars[i]) << 4) | (try nibble(chars[i + 1])))
            i += 2
        }
        return out
    }

    static func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }

    // MARK: Access

    private func dictionary(_ path: [String]) throws -> [String: Any] {
        var current: Any = root
        for key in path {
            guard let next = (current as? [String: Any])?[key] else { throw KatError(description: "missing " + path.joined(separator: ".")) }
            current = next
        }
        guard let result = current as? [String: Any] else { throw KatError(description: "not an object: " + path.joined(separator: ".")) }
        return result
    }

    func hex(_ path: [String]) throws -> Data {
        guard let key = path.last else { throw KatError(description: "empty path") }
        let parent = try dictionary(Array(path.dropLast()))
        guard let text = parent[key] as? String else { throw KatError(description: "missing " + path.joined(separator: ".")) }
        return try Self.data(text)
    }

    func string(_ path: [String]) throws -> String {
        guard let key = path.last else { throw KatError(description: "empty path") }
        let parent = try dictionary(Array(path.dropLast()))
        guard let text = parent[key] as? String else { throw KatError(description: "missing " + path.joined(separator: ".")) }
        return text
    }

    func input(_ key: String) throws -> Data { try hex(["exchange", "inputs", key]) }
    func derived(_ key: String) throws -> Data { try hex(["exchange", "derived", key]) }

    func party(_ role: String) throws -> (seed: Data, publicKey: Data, userId: String, block: Data) {
        let seed = try hex(["exchange", "inputs", role, "ed25519Seed"])
        let pub = try hex(["exchange", "inputs", role, "idPub"])
        let userId = try string(["exchange", "inputs", role, "userId"])
        let block = try hex(["exchange", "inputs", role, "idBlock"])
        return (seed, pub, userId, block)
    }

    var negatives: [[String: Any]] {
        (root["negative"] as? [[String: Any]]) ?? []
    }

    func negative(_ name: String) throws -> [String: Any] {
        guard let entry = negatives.first(where: { ($0["name"] as? String) == name }) else {
            throw KatError(description: "missing negative " + name)
        }
        return entry
    }

    func apdus() throws -> [(name: String, command: Data, response: Data)] {
        guard let list = (try dictionary(["exchange"]))["apdus"] as? [[String: Any]] else { throw KatError(description: "no apdus") }
        return try list.map { item in
            guard let name = item["name"] as? String, let c = item["command"] as? String, let r = item["response"] as? String else {
                throw KatError(description: "malformed apdu")
            }
            return (name, try Self.data(c), try Self.data(r))
        }
    }

    // MARK: Ready-made values for the tests

    struct Session1 {
        let reader: (seed: Data, publicKey: Data, userId: String, block: Data)
        let card: (seed: Data, publicKey: Data, userId: String, block: Data)
        let ek: Data
        let ct: Data
        let kemSharedSecret: Data
        let sealedCard: Data
        let sealedReader: Data
        let th1: Data
        let stage1: NfcPairingV2Crypto.Stage1
        let thCard: Data
        let commitReader: Data
        let nonceReader: Data
        let nonceCard: Data
    }

    func session1() throws -> Session1 {
        let reader = try party("reader")
        let card = try party("card")
        let th1 = try derived("th1")
        let stage1 = try NfcPairingV2Crypto.deriveStage1(th1: th1, kemSharedSecret: try input("mlkemSs"),
                                                         x25519SharedSecret: try derived("ssX25519"))
        return Session1(reader: reader, card: card, ek: try input("mlkemEk"), ct: try input("mlkemCt"),
                        kemSharedSecret: try input("mlkemSs"), sealedCard: try derived("sealedCard"),
                        sealedReader: try derived("sealedReader"), th1: th1, stage1: stage1,
                        thCard: try derived("thCard"), commitReader: try derived("commitReader"),
                        nonceReader: try input("nonceReader"), nonceCard: try input("nonceCard"))
    }

    /// The random values of the reader of the vector exchange.
    func readerEntropy() throws -> NfcReaderEntropy {
        let pair = try ProximityPairingCrypto.kemGenerateKeyPair(seed: try input("mlkemSeedReader"))
        guard pair.publicKey == (try input("mlkemEk")) else { throw KatError(description: "ek does not match its seed") }
        return NfcReaderEntropy(
            x25519Private: try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: try input("x25519PrivReader")),
            kemPublicKey: pair.publicKey, kemSecretKey: pair.secretKey, nonce: try input("nonceReader"))
    }

    /// A card that takes the vector's values as given.
    func card(sealedAuth: Data? = nil) throws -> NfcCardSimulator {
        let card = try party("card")
        let simulator = try NfcCardSimulator(seed: card.seed, publicKey: card.publicKey, userId: card.userId)
        simulator.fixed = NfcCardSimulator.Fixed(
            xPrivate: try input("x25519PrivCard"), nonce: try input("nonceCard"), ciphertext: try input("mlkemCt"),
            kemSharedSecret: try input("mlkemSs"), sealedAuth: try sealedAuth ?? derived("sealedCard"))
        return simulator
    }

    func readerIdentity() throws -> NfcPairingV2LocalIdentity {
        let reader = try party("reader")
        return NfcPairingV2LocalIdentity(identity: try NfcPairingV2Identity(publicKey: reader.publicKey, userId: reader.userId),
                                         signingPrivateKey: reader.seed)
    }
}
